// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free      []T
	next      int
	bootstrap uint8
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew allocates the first three values independently so a later
// published value cannot retain discarded early siblings through a chunk.
// Later values use the original 8-to-256 chunk growth.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		if s.bootstrap < 3 {
			s.bootstrap++
			return new(T)
		}
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice allocates the first nonempty small list independently to keep
// its backing values separate from later published lists of the same type.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		if s.bootstrap == 0 {
			s.bootstrap = 1
			return make([]T, n)
		}
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	trules[16].text = func(p *tparser, start, end int, text string) tval {
		p.stepWork()
		v := astNew(&p.ext.(*tslabs).tIdent)
		*v = Ident{Span: Span{start, end}, Text: text}
		return v
	}
	trules[20].text = func(p *tparser, start, end int, text string) tval {
		p.stepWork()
		v := astNew(&p.ext.(*tslabs).tNumber)
		*v = Number{Span: Span{start, end}, Text: text}
		return v
	}
	trules[22].text = func(p *tparser, start, end int, text string) tval {
		p.stepWork()
		v := astNew(&p.ext.(*tslabs).tString)
		*v = String{Span: Span{start, end}, Text: text}
		return v
	}
	trules[23].text = func(p *tparser, start, end int, text string) tval {
		p.stepWork()
		v := astNew(&p.ext.(*tslabs).tBool)
		*v = Bool{Span: Span{start, end}, Text: text}
		return v
	}
}

