func tv9(a *tslabs, v any) *TNode[Tuple1[*TNode[string]]] {
	a.stepWork()
	switch x := v.(type) {
	case *tnode:
		if x.typ == typeTupleValue || x.typ == typeListValue {
			return nil
		}
		out := &TNode[Tuple1[*TNode[string]]]{Span: x.Span}
		out.Value = tv12(a, x)
		return out
	case *terror:
		return nil
	case tval:
		if x.tstruct() {
			return nil
		}
		s, e := x.tspan()
		text, _ := x.ttext()
		_ = text
		out := &TNode[Tuple1[*TNode[string]]]{Span: Span{s, e}}
		out.Value = tv12(a, text)
		return out
	}
	return nil
}

